  app.post('/api/pink-salt/customers/:id/adjustments-v313',auth,allow('sales','finance'),(req,res)=>{const bu=guard(req,res);if(!bu)return;const c=db.prepare('SELECT * FROM pink_salt_customers WHERE id=? AND business_unit_id=?').get(req.params.id,bu);if(!c)return res.status(404).json({error:'Customer not found.'});const amount=Math.max(0,num(req.body.amount_krw)),effect=text(req.body.effect)==='Debit'?'Debit':'Credit',type=text(req.body.adjustment_type)||'Account Adjustment',reference=text(req.body.reference),d=text(req.body.adjustment_date)||today();if(amount<=0||!reference)return res.status(400).json({error:'Adjustment amount and reference are required.'});try{let jid=null;const r=db.prepare("INSERT INTO pink_salt_customer_adjustments(business_unit_id,customer_id,adjustment_date,adjustment_type,effect,amount_krw,reference,notes,status,created_by) VALUES(?,?,?,?,?,?,?,?, 'Active',?)").run(bu,c.id,d,type,effect,amount,reference,text(req.body.notes),req.user.id),id=Number(r.lastInsertRowid);if(accounting?.postJournal){jid=accounting.postJournal({businessUnitId:bu,transactionDate:d,sourceType:'Pink Salt Customer Adjustment',sourceId:id,sourceLabel:`${type} · ${c.name}`,description:`${effect} customer adjustment · ${reference}`,createdBy:req.user.id,lines:effect==='Credit'?[{account_id:accounting.accountId('PINK_SALT_SALES_REVENUE'),debit_krw:amount,credit_krw:0,entity_type:'Pink Salt Customer',entity_id:c.id,memo:`Credit note / adjustment · ${reference}`},{account_id:accounting.accountId('ACCOUNTS_RECEIVABLE'),debit_krw:0,credit_krw:amount,entity_type:'Pink Salt Customer',entity_id:c.id,memo:`Reduce customer receivable · ${reference}`}]:[{account_id:accounting.accountId('ACCOUNTS_RECEIVABLE'),debit_krw:amount,credit_krw:0,entity_type:'Pink Salt Customer',entity_id:c.id,memo:`Debit note / adjustment · ${reference}`},{account_id:accounting.accountId('PINK_SALT_SALES_REVENUE'),debit_krw:0,credit_krw:amount,entity_type:'Pink Salt Customer',entity_id:c.id,memo:`Increase customer charge · ${reference}`}]});db.prepare('UPDATE pink_salt_customer_adjustments SET journal_entry_id=? WHERE id=?').run(jid,id)}audit(req.user,'pink_salt_customer_adjustment',id,'create',JSON.stringify({type,effect,amount,reference}));res.json({id,journal_entry_id:jid})}catch(e){res.status(409).json({error:e.message})}});

  function ledger(customerId,from='',to=''){
    const entries=[];for(const o of db.prepare("SELECT * FROM pink_salt_orders WHERE customer_id=? AND status='Completed' ORDER BY order_date,id").all(customerId))entries.push({date:o.order_date,type:'Sale / Invoice',reference:o.order_no,debit:num(o.total_krw),credit:0,details:o.sales_channel||''});for(const p of db.prepare("SELECT p.*,o.order_no FROM pink_salt_customer_payments p JOIN pink_salt_orders o ON o.id=p.order_id WHERE p.customer_id=? AND p.status='Active' ORDER BY p.payment_date,p.id").all(customerId))entries.push({date:p.payment_date,type:'Legacy Payment',reference:p.reference,details:p.order_no,debit:0,credit:num(p.krw_amount)});for(const r of db.prepare("SELECT * FROM pink_salt_customer_receipts WHERE customer_id=? AND status='Active' ORDER BY payment_date,id").all(customerId))entries.push({date:r.payment_date,type:'Payment / Settlement',reference:r.reference,details:r.payment_method,debit:0,credit:num(r.gross_settlement_krw)});for(const r of db.prepare("SELECT r.*,o.order_no FROM pink_salt_customer_refunds r JOIN pink_salt_orders o ON o.id=r.order_id WHERE r.customer_id=? AND r.status='Active' ORDER BY r.refund_date,r.id").all(customerId))entries.push({date:r.refund_date,type:'Refund',reference:r.reference,details:r.order_no,debit:num(r.krw_amount),credit:0});for(const a of db.prepare("SELECT * FROM pink_salt_customer_adjustments WHERE customer_id=? AND status='Active' ORDER BY adjustment_date,id").all(customerId))entries.push({date:a.adjustment_date,type:a.adjustment_type,reference:a.reference,details:a.notes,debit:a.effect==='Debit'?num(a.amount_krw):0,credit:a.effect==='Credit'?num(a.amount_krw):0});entries.sort((a,b)=>String(a.date).localeCompare(String(b.date))||String(a.type).localeCompare(String(b.type)));const before=e=>from&&e.date<from,within=e=>(!from||e.date>=from)&&(!to||e.date<=to);const opening=entries.filter(before).reduce((n,e)=>n+e.debit-e.credit,0);let balance=opening;const rows=entries.filter(within).map(e=>({...e,balance:(balance+=e.debit-e.credit)}));return {opening_balance_krw:opening,rows,closing_balance_krw:balance};
  }
  app.get('/api/pink-salt/customers/:id/statement-v313',auth,allow('sales','finance','dashboard'),(req,res)=>{const bu=guard(req,res);if(!bu)return;const c=db.prepare('SELECT * FROM pink_salt_customers WHERE id=? AND business_unit_id=?').get(req.params.id,bu);if(!c)return res.status(404).json({error:'Customer not found.'});const from=text(req.query.from),to=text(req.query.to),l=ledger(c.id,from,to);res.json({customer:c,from,to,...l})});
  app.get('/api/pink-salt/customers/:id/statement-v313.csv',auth,allow('sales','finance','dashboard'),(req,res)=>{const bu=guard(req,res);if(!bu)return;const c=db.prepare('SELECT * FROM pink_salt_customers WHERE id=? AND business_unit_id=?').get(req.params.id,bu);if(!c)return res.status(404).send('Customer not found');const from=text(req.query.from),to=text(req.query.to),l=ledger(c.id,from,to),csv=v=>'"'+String(v??'').replaceAll('"','""')+'"';const lines=[['Date','Type','Reference','Details','Debit KRW','Credit KRW','Balance KRW'].map(csv).join(',')];lines.push(['','Opening Balance','','',l.opening_balance_krw,0,l.opening_balance_krw].map(csv).join(','));for(const r of l.rows)lines.push([r.date,r.type,r.reference,r.details,r.debit,r.credit,r.balance].map(csv).join(','));res.setHeader('Content-Type','text/csv; charset=utf-8');res.setHeader('Content-Disposition',`attachment; filename="${String(c.name).replace(/[^a-z0-9_-]+/gi,'_')}_statement.csv"`);res.send('\ufeff'+lines.join('\n'))});
  function chromePath(){const a=[process.env.CHROME_PATH,process.env.GOOGLE_CHROME_BIN,'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome','/usr/bin/chromium','/usr/bin/chromium-browser','/usr/bin/google-chrome','/usr/bin/google-chrome-stable'];return a.find(x=>x&&fs.existsSync(x))||''}
  function htmlStatement(c,l,from,to,lang='en'){const ko=lang==='ko',money=v=>Math.round(num(v)).toLocaleString('en-US'),escHtml=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));return `<!doctype html><html><head><meta charset="utf-8"><style>@page{size:A4;margin:14mm}body{font-family:"Noto Sans KR","Apple SD Gothic Neo",Arial,sans-serif;color:#162033;font-size:10px}h1{font-size:20px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #dfe5ee;padding:5px}th{background:#f4f6f8}.r{text-align:right}.muted{color:#667085}.summary{display:flex;gap:12px;margin:12px 0}.box{border:1px solid #dfe5ee;padding:8px;border-radius:6px;flex:1}</style></head><body><h1>${ko?'고객 / 매장 거래명세서':'Customer / Store Statement'}</h1><div><b>${escHtml(c.name)}</b><br><span class="muted">${escHtml(from||'Beginning')} — ${escHtml(to||today())}</span></div><div class="summary"><div class="box">${ko?'기초 잔액':'Opening Balance'}<br><b>₩ ${money(l.opening_balance_krw)}</b></div><div class="box">${ko?'마감 잔액':'Closing Balance'}<br><b>₩ ${money(l.closing_balance_krw)}</b></div></div><table><tr><th>${ko?'날짜':'Date'}</th><th>${ko?'유형':'Type'}</th><th>${ko?'참조':'Reference'}</th><th>${ko?'상세':'Details'}</th><th>${ko?'청구':'Debit'}</th><th>${ko?'입금 / 크레딧':'Credit'}</th><th>${ko?'잔액':'Balance'}</th></tr>${l.rows.map(r=>`<tr><td>${escHtml(r.date)}</td><td>${escHtml(r.type)}</td><td>${escHtml(r.reference)}</td><td>${escHtml(r.details)}</td><td class="r">₩ ${money(r.debit)}</td><td class="r">₩ ${money(r.credit)}</td><td class="r">₩ ${money(r.balance)}</td></tr>`).join('')}</table></body></html>`}
  app.get('/api/pink-salt/customers/:id/statement-v313.pdf',auth,allow('sales','finance','dashboard'),(req,res)=>{const bu=guard(req,res);if(!bu)return;const c=db.prepare('SELECT * FROM pink_salt_customers WHERE id=? AND business_unit_id=?').get(req.params.id,bu);if(!c)return res.status(404).json({error:'Customer not found.'});const from=text(req.query.from),to=text(req.query.to),lang=String(req.query.lang||'en').toLowerCase().startsWith('ko')?'ko':'en',l=ledger(c.id,from,to),chrome=chromePath();if(!chrome)return res.status(409).json({error:'PDF generation requires Google Chrome or Chromium on the server. CSV export is available without Chrome.'});const tmp=path.join(os.tmpdir(),`ps-statement-${c.id}-${Date.now()}.html`),out=path.join(os.tmpdir(),`ps-statement-${c.id}-${Date.now()}.pdf`);try{fs.writeFileSync(tmp,htmlStatement(c,l,from,to,lang));execFileSync(chrome,['--headless','--no-sandbox','--disable-gpu',`--print-to-pdf=${out}`,`file://${tmp}`],{stdio:'ignore',timeout:30000});if(!fs.existsSync(out))throw new Error('PDF generation failed.');res.download(out,`${String(c.name).replace(/[^a-z0-9_-]+/gi,'_')}_statement.pdf`,()=>{try{fs.unlinkSync(out)}catch(_){}})}catch(e){res.status(409).json({error:e.message})}finally{try{fs.unlinkSync(tmp)}catch(_){}}});

  app.get('/api/pink-salt/dashboard-v313',auth,allow('dashboard','inventory','purchases','sales','finance'),(req,res)=>{const bu=guard(req,res);if(!bu)return;const orders=db.prepare("SELECT * FROM pink_salt_orders WHERE business_unit_id=? AND status='Completed'").all(bu);let receivables=0;for(const o of orders)receivables+=orderFinancials(o).outstanding_krw;const month=today().slice(0,7),legacy=num(db.prepare("SELECT COALESCE(SUM(p.krw_amount),0) v FROM pink_salt_customer_payments p JOIN pink_salt_orders o ON o.id=p.order_id WHERE o.business_unit_id=? AND p.status='Active' AND substr(p.payment_date,1,7)=?").get(bu,month)?.v),receipts=num(db.prepare("SELECT COALESCE(SUM(gross_settlement_krw),0) v FROM pink_salt_customer_receipts WHERE business_unit_id=? AND status='Active' AND substr(payment_date,1,7)=?").get(bu,month)?.v);res.json({customer_receivables_krw:receivables,month_customer_receipts_krw:legacy+receipts})});

